  const { candidates, ballots } = election
  let continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let majority = null
    for (const [name, count] of votes) {
      if (count * 2 > activeTotal) majority = name
    }

    if (majority !== null) {
      winner = majority
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const minVotes = Math.min(...votes.values())
    const fewest = [...votes.keys()].filter((name) => votes.get(name) === minVotes)
    const eliminated = fewest.length === 1 ? fewest[0] : breakTie(fewest, history)

    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
